            lines.append((len(rs)+len(cs), color, rs, cs))
    if not lines:
        return [row[:] for row in grid]
    _, sep, rs, cs = max(lines)
    rb=[-1]+rs+[h]; cb=[-1]+cs+[w]
    rgs=[(rb[i]+1,rb[i+1]) for i in range(len(rb)-1)]
    cgs=[(cb[i]+1,cb[i+1]) for i in range(len(cb)-1)]
    panels=[(a,b,c,d) for a,b in rgs for c,d in cgs if a<b and c<d]
    background=max(range(10),key=lambda v:sum(row.count(v) for row in grid))
    src=max(panels,key=lambda p:sum(grid[r][c]!=background for r in range(p[0],p[1]) for c in range(p[2],p[3])))
    a,b,c,d=src; ph,pw=b-a,d-c
    out=[row[:] for row in grid]
    for y0,y1,x0,x1 in panels:
        for r in range(y0,y1):
            for x in range(x0,x1):
                out[r][x]=grid[a+(r-y0)%ph][c+(x-x0)%pw]
    return out
