{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-openclaw-luna6-low-seq0/frozen/seen/play/users/u010/system/state/workspace/programs/task-d0344666.py",
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The demonstrations show copying the richer pattern region across a
    # full-width divider; preserve the divider and tile source rows as needed.
    row_lines = {}
    for color in range(10):
        row_lines[color] = [r for r in range(h) if all(v == color for v in grid[r])]
    candidates = []
    for color, rows in row_lines.items():
        for r in rows:
            # A single interior uniform row acts as the horizontal divider.
            if (r == 0 or r - 1 not in rows) and (r == h - 1 or r + 1 not in rows):
                if 0 < r < h - 1:
                    candidates.append((color, r))
    if not candidates:
        return [row[:] for row in grid]
    sep_color, sep = min(candidates, key=lambda q: sum(row.count(q[0]) for row in grid))
    top, bottom = grid[:sep], grid[sep + 1:]
    bg = max(range(10), key=lambda v: sum(row.count(v) for row in grid))
    detail_top = sum(v != bg and v != sep_color for row in top for v in row)
    detail_bottom = sum(v != bg and v != sep_color for row in bottom for v in row)
    src = top if detail_top >= detail_bottom else bottom
    out = [row[:] for row in grid]
    dst_start, dst_len = (sep + 1, len(bottom)) if src is top else (0, len(top))
    for i in range(dst_len):
        out[dst_start + i] = src[i % len(src)][:]
    return out
